# area: inheritance_mro
# hypothesis: In a diamond hierarchy, C3 linearization sends super() through both branches, and an override that narrows a str parameter to int is an LSP violation that mypy and ty should reject while CPython runs it without error.
from typing import reveal_type


class Base:
    def greet(self, name: str) -> str:
        return f'base {name}'


class Left(Base):
    def greet(self, name: str) -> str:
        return 'left ' + super().greet(name)


class Right(Base):
    def greet(self, name: str) -> str:
        return 'right ' + super().greet(name)


class Diamond(Left, Right):
    def greet(self, name: str) -> str:
        return 'diamond ' + super().greet(name)


class Narrow(Base):
    def greet(self, name: int) -> str:  # expect-error
        return f'narrow {name}'


d = Diamond()
reveal_type(Diamond.__mro__)
assert [c.__name__ for c in Diamond.__mro__] == ['Diamond', 'Left', 'Right', 'Base', 'object']
assert d.greet('x') == 'diamond left right base x'
assert Base().greet('a') == 'base a'
assert Left().greet('b') == 'left base b'
assert Right().greet('c') == 'right base c'
assert Narrow().greet(3) == 'narrow 3'
